#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# step6_sandwich_squeeze/scripts/70_install_trainer_shim.sh
#
#   Registers nnUNetTrainerSandwich with the **zk** environment.
#
#   WHY: `~/anaconda3/envs/zk` ships nnunetv2 **2.6.2**.  Its `-tr <Name>`
#   lookup only iterates the FILES inside
#       <site-packages>/nnunetv2/training/nnUNetTrainer
#   (no nnUNet_extTrainer support before 2.8).  The real implementation stays
#   in step6/trainer (single source of truth); the generated file only puts
#   that directory on sys.path and re-exports the class, so both training and
#   inference (the predictor re-imports the trainer named in the checkpoint)
#   resolve it.
#
#   Idempotent.  Delete the generated file to unregister.
#
#   usage: bash scripts/70_install_trainer_shim.sh
# ---------------------------------------------------------------------------
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
source scripts/env_step6.sh

SHIM_DIR="$("$STEP6_VENV/bin/python" -c 'import os, nnunetv2; print(os.path.join(nnunetv2.__path__[0], "training", "nnUNetTrainer"))')"
TARGET="$SHIM_DIR/nnUNetTrainerStep6Sandwich.py"
TRAINER_DIR="$STEP6_ROOT/trainer"

echo "[shim] venv            = $STEP6_VENV"
echo "[shim] nnunetv2        = $("$STEP6_VENV/bin/python" -c 'import nnunetv2; print(getattr(nnunetv2, "__version__", "unknown"))')"
echo "[shim] target          = $TARGET"
echo "[shim] re-exports from = $TRAINER_DIR"

cat > "$TARGET" <<PYEOF
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
SHIM -- makes the step-6 SANDWICH SQUEEZE (夹逼定理 v2) trainer discoverable by
this nnU-Net install.

GENERATED by step6_sandwich_squeeze/scripts/70_install_trainer_shim.sh
Do not edit here; edit that script so the shim stays reproducible.

Why it exists: zk's nnunetv2 2.6.2 resolves a trainer only by scanning the
files inside <site-packages>/nnunetv2/training/nnUNetTrainer.  The real
implementation stays in the project:

    $TRAINER_DIR

This file carries no logic; it puts that directory on sys.path and re-exports
the class.  Delete it to unregister.
"""
import sys

_TRAINER_DIR = ("$TRAINER_DIR")
if _TRAINER_DIR not in sys.path:
    sys.path.insert(0, _TRAINER_DIR)

from nnUNetTrainerSandwich import nnUNetTrainerSandwich        # noqa: E402,F401
from nnUNetTrainerSandwichW25 import (nnUNetTrainerSandwichW25,  # noqa: E402,F401
                                      nnUNetTrainerSandwichW25s)
from nnUNetTrainerSandwichResencW25 import nnUNetTrainerSandwichResencW25  # noqa: E402,F401

__all__ = ["nnUNetTrainerSandwich", "nnUNetTrainerSandwichW25",
           "nnUNetTrainerSandwichW25s", "nnUNetTrainerSandwichResencW25"]
PYEOF

echo "[shim] verifying the registration the way nnU-Net resolves it ..."
"$STEP6_VENV/bin/python" - <<'PYEOF'
import os
import sys

import torch
import nnunetv2
from nnunetv2.utilities.find_class_by_name import recursive_find_python_class

folder = os.path.join(nnunetv2.__path__[0], "training", "nnUNetTrainer")
want = ["nnUNetTrainerSandwich", "nnUNetTrainerSandwichW25", "nnUNetTrainerSandwichW25s",
        "nnUNetTrainerSandwichResencW25"]
c = None
bad = []
for name in want:
    c = recursive_find_python_class(folder, name, 'nnunetv2.training.nnUNetTrainer')
    print("[shim] %-28s -> %s" % (name, c))
    if c is None:
        bad.append(name)
if bad:
    sys.exit(1)

# the 3-version network must also be constructible through the registration path
kw = {"n_stages": 4, "features_per_stage": [4, 8, 16, 32],
      "conv_op": "torch.nn.modules.conv.Conv2d",
      "kernel_sizes": [[3, 3]] * 4, "strides": [[1, 1]] + [[2, 2]] * 3,
      "n_conv_per_stage": [1, 1, 1, 1], "n_conv_per_stage_decoder": [1, 1, 1],
      "conv_bias": True, "norm_op": "torch.nn.modules.instancenorm.InstanceNorm2d",
      "norm_op_kwargs": {"eps": 1e-05, "affine": True},
      "dropout_op": None, "dropout_op_kwargs": None,
      "nonlin": "torch.nn.LeakyReLU", "nonlin_kwargs": {"inplace": True}}
net = c.build_network_architecture(
    "dynamic_network_architectures.architectures.unet.PlainConvUNet",
    kw, ["conv_op", "norm_op", "dropout_op", "nonlin"], 1, 2,
    enable_deep_supervision=True)
# training mode (the trainer switches this on in on_train_start)
net.set_forward_mode("all")
out = net(torch.zeros(1, 1, 64, 64))
print("[shim] training forward ->", [tuple(o.shape) for o in out][:2])
assert isinstance(out, (list, tuple)) and out[0].shape[1] == 6, \
    "the 3-version output is not 6 channels"
# inference modes (what the stock predictor sees)
net.set_forward_mode("base")
out2 = net(torch.zeros(1, 1, 64, 64))
print("[shim] inference forward ->", tuple(out2.shape))
assert tuple(out2.shape) == (1, 2, 64, 64), "the base version did not collapse to 2 channels"
print("[shim] OK - trainer resolves and the 3-version network builds")
PYEOF
